import{_ as t,o as d,c as o,a3 as e}from"./chunks/framework.CWYzGJW1.js";const k=JSON.parse('{"title":"30 天 PoC 計畫","description":"以 30 天, 一台既有機器, 最小組合驗證三件事: 能不能跑, 品質夠不夠, 維運扛不扛得住.","frontmatter":{"description":"以 30 天, 一台既有機器, 最小組合驗證三件事: 能不能跑, 品質夠不夠, 維運扛不扛得住."},"headers":[],"relativePath":"decide/poc-30days.md","filePath":"decide/poc-30days.md","lastUpdated":1793035092000}'),r={name:"decide/poc-30days.md"};function i(n,a,l,h,s,b){return d(),o("div",null,[...a[0]||(a[0]=[e('<h1 id="_30-天-poc-計畫" tabindex="-1">30 天 PoC 計畫 <a class="header-anchor" href="#_30-天-poc-計畫" aria-label="Permalink to &quot;30 天 PoC 計畫&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本頁屬性</p><ul><li>等級: 決策參考</li><li>狀態: 可閱讀 (部分資料待核對)</li><li>資料基準日: 2026-10-26</li><li>待查證: 週次與時數為整理者建議 (信心: 低, 屬推論), 請依團隊規模調整; 本頁無外部來源, 見頁尾「資料來源」</li></ul></div><p><strong>結論</strong>: 以 30 天, 一台既有機器, 最小組合驗證三件事: 能不能跑, 品質夠不夠, 維運扛不扛得住. 第 30 天依事先寫好的標準決定繼續, 調整或停止. PoC (Proof of Concept, 概念驗證) 的用意, 是在購買硬體之前先用最少的成本確認方向.</p><h2 id="開始前-先寫下成功標準" tabindex="-1">開始前: 先寫下成功標準 <a class="header-anchor" href="#開始前-先寫下成功標準" aria-label="Permalink to &quot;開始前: 先寫下成功標準&quot;">​</a></h2><p>成功標準要在動手前寫下. 試做結束時才有事先約定的依據, 不會因為已經投入時間而放寬標準.</p><table tabindex="0"><thead><tr><th>欄位</th><th>填寫</th></tr></thead><tbody><tr><td>要驗證的任務 (一至三項)</td><td></td></tr><tr><td>品質標準</td><td>例: 自建 50 題中, 達到多少題可接受 (自行訂定)</td></tr><tr><td>維運標準</td><td>例: 每週維運工時不超過多少 (自行訂定)</td></tr><tr><td>停止條件</td><td>例: 品質標準未達, 或安全自評低於 5 題</td></tr></tbody></table><h2 id="四週安排" tabindex="-1">四週安排 <a class="header-anchor" href="#四週安排" aria-label="Permalink to &quot;四週安排&quot;">​</a></h2><p>四週由淺入深: 第 1 週確認能跑, 第 2 週確認品質, 第 3 週補上安全與備份, 第 4 週讓實際使用者試用. 表中的「最小組合」是能對話所需的最少元件 (見<a href="/lanai-handbook/start/map">架構地圖</a>的里程碑 1); 嵌入模型負責依意思找出相關段落 (見 <a href="/lanai-handbook/know/k1-basics">K1</a>); 升級回退是新版本出問題時換回上一版的做法 (見 <a href="/lanai-handbook/ops/versioning">O2</a>).</p><table tabindex="0"><thead><tr><th>週</th><th>目標</th><th>產出</th><th>對應章節</th></tr></thead><tbody><tr><td>第 1 週</td><td>在既有機器上跑出第一個對話, 記錄硬體規格與耗時</td><td>可運作的最小組合, 規格紀錄</td><td><a href="/lanai-handbook/">使用說明</a>, <a href="/lanai-handbook/know/k2-quantization">K2</a>, <a href="/lanai-handbook/build/m1-inference">M1</a></td></tr><tr><td>第 2 週</td><td>建立 50 題測試集, 比較兩個候選模型; 需要檢索時一併測嵌入模型</td><td>測試集與結果表</td><td><a href="/lanai-handbook/build/m4-retrieval">M4</a>, <a href="/lanai-handbook/build/m6-observability">M6</a></td></tr><tr><td>第 3 週</td><td>加上帳號, 網路隔離, 備份; 做一次還原演練與一次升級回退</td><td>風險自評結果, 備份與回退紀錄</td><td><a href="/lanai-handbook/know/k6-security">K6</a>, <a href="/lanai-handbook/ops/backup">O1</a>, <a href="/lanai-handbook/ops/versioning">O2</a></td></tr><tr><td>第 4 週</td><td>讓 3 至 5 位實際使用者試用, 蒐集意見並記錄維運工時</td><td>使用回饋, 成本實績</td><td><a href="/lanai-handbook/decide/tco">成本試算表</a></td></tr></tbody></table><h2 id="第-30-天-決策" tabindex="-1">第 30 天: 決策 <a class="header-anchor" href="#第-30-天-決策" aria-label="Permalink to &quot;第 30 天: 決策&quot;">​</a></h2><table tabindex="0"><thead><tr><th>結果</th><th>做法</th></tr></thead><tbody><tr><td>品質與維運標準都達成</td><td>進入正式評估, 規劃硬體與維運人力</td></tr><tr><td>品質達成, 維運吃力</td><td>縮減元件, 或評估雲端或託管方案</td></tr><tr><td>品質未達成</td><td>換模型, 調整檢索設計, 或回到雲端 API</td></tr><tr><td>安全自評缺口大</td><td>先補齊缺口, 不對外開放</td></tr></tbody></table><h2 id="注意事項" tabindex="-1">注意事項 <a class="header-anchor" href="#注意事項" aria-label="Permalink to &quot;注意事項&quot;">​</a></h2><ul><li>PoC 期間只使用不敏感的資料, 或確認測試環境與正式資料隔離.</li><li>每週固定記錄實際工時, 這是成本試算最缺的數字.</li><li>所有元件版本在第 1 週就鎖定並記錄, 避免 PoC 中途更新而影響結果.</li></ul><h2 id="參考來源" tabindex="-1">參考來源 <a class="header-anchor" href="#參考來源" aria-label="Permalink to &quot;參考來源&quot;">​</a></h2><p>本頁為整理者依本手冊各章整理的 PoC 規劃框架, 沒有引用外部方法論, 市場資料或統計數字.</p><ul><li><strong>四週安排, 50 題測試集, 3 至 5 位試用者, 「安全自評低於 5 題」的停止條件</strong>: 皆為整理者建議值 (推論, 信心: 低). 表中的「達到多少題」「工時不超過多少」是填寫欄位, 由讀者依自己的情況訂定.</li><li><strong>各週對應章節的做法</strong>: 依據在所連結章節的「參考來源」: 模型與量化見 <a href="/lanai-handbook/know/k2-quantization">K2</a> 與 <a href="/lanai-handbook/build/m1-inference">M1</a>, 評測見 <a href="/lanai-handbook/build/m4-retrieval">M4</a> 與 <a href="/lanai-handbook/build/m6-observability">M6</a>, 帳號, 隔離, 備份與回退見 <a href="/lanai-handbook/know/k6-security">K6</a>, <a href="/lanai-handbook/ops/backup">O1</a>, <a href="/lanai-handbook/ops/versioning">O2</a>.</li><li><strong>風險自評的題目與門檻</strong>: 見<a href="/lanai-handbook/decide/risk-checklist">風險自評</a>的參考來源.</li><li><strong>成本實績</strong>: 由第 4 週記錄的工時填入<a href="/lanai-handbook/decide/tco">成本試算表</a>, 該頁同樣不含市場價格.</li></ul>',16)])])}const f=t(r,[["render",i]]);export{k as __pageData,f as default};
